commands.cmd:
mkdir -p tmp && git show HEAD:src/components/features/auth/prototype/screens.tsx > src/components/features/auth/prototype/screens.before.tsx && mkdir -p 'src/app/[locale]/auth/signup/qa-grace' && cat > 'src/app/[locale]/auth/signup/qa-grace/page.tsx' <<'EOF'
'use client';
import { useSearchParams } from 'next/navigation';
import * as After from '@/components/features/auth/prototype/screens';
import * as Before from '@/components/features/auth/prototype/screens.before';
import { PrototypeAuthShell } from '@/components/features/auth/prototype';
import { SecurityStepupModal } from '@/components/modals/security/security-stepup-modal';
import { useTranslations } from 'next-intl';

export default function Evidence() {
  const params = useSearchParams();
  const before = params.get('version') === 'before';
  const state = params.get('state') ?? 'select-ending';
  const Screens = before ? Before : After;
  const t = useTranslations('auth.prototypeAuth');
  const expiry = Date.now() + (state.endsWith('ending') ? 42_000 : 600_000);
  const noop = () => {};
  const factor = state.includes('totp') ? 'totp' : 'passkey';
  let card;
  if (state.startsWith('select')) card = <Screens.SecuritySetup testId="select" onPick={noop} onSkip={noop} {...(!before ? {graceExpiresAt: expiry} : {})} />;
  else if (state.startsWith('passkey')) card = <Screens.PasskeySetup onCreate={noop} onSkip={noop} onBack={noop} {...(!before ? {graceExpiresAt: expiry} : {})} />;
  else if (state === 'totp') card = <Screens.TotpSetup secret="JBSWY3DPEHPK3PXP" otpauthUrl="otpauth://totp/Crpko:test?secret=JBSWY3DPEHPK3PXP&issuer=Crpko" code="" onCodeChange={noop} onBack={noop} />;
  else if (state === 'auto-ready') card = <Screens.AuthStatus variant="complete" title={t('complete.title')} subtitle={!before ? <span role="status">{t('quickSetup.ended')}</span> : t('complete.subtitle')} primaryLabel={t('complete.startTrading')} onPrimary={noop} testId="complete" />;
  else if (state.startsWith('expired') && !before) card = <After.SetupExpired factor={factor} onContinue={noop} onSkip={noop} onBack={noop} />;
  else card = <Screens.SecuritySetup testId="select" onPick={noop} onSkip={noop} />;
  const modal = state.startsWith('no-window') || (before && state.startsWith('expired')) || state === 'stepup';
  return <PrototypeAuthShell>{card}<SecurityStepupModal isOpen={modal} onClose={noop} submit={async()=> 'done'} {...(!before ? {title:t('quickSetup.checkTitle'), purposeLabel:t(factor === 'totp' ? 'quickSetup.totpBody' : 'quickSetup.passkeyBody')} : {})} /></PrototypeAuthShell>;
}
EOF
node node_modules/prettier/bin/prettier.cjs --write 'src/app/[locale]/auth/signup/qa-grace/page.tsx' >/dev/null
printf '\nsrc/components/features/auth/prototype/screens.before.tsx\nsrc/app/\n' > tmp/evidence-excludes-note
cat .git/info/exclude | tail -5
